TAILS_n,COALESCE(SUM(CASE WHEN total_amount<>0 AND fee_n=0 THEN ABS(total_amount) ELSE 0 END),0) AS MISSING_DETAILS_diff,COALESCE(SUM(CASE WHEN total_amount IS NULL OR paid_amount IS NULL OR unpaid_amount IS NULL OR NOT(total_amount <=> paid_amount+unpaid_amount+red_amount) THEN 1 ELSE 0 END),0) AS BALANCE_n,COALESCE(SUM(CASE WHEN total_amount IS NULL OR paid_amount IS NULL OR unpaid_amount IS NULL OR NOT(total_amount <=> paid_amount+unpaid_amount+red_amount) THEN ABS(total_amount-paid_amount-unpaid_amount-red_amount) ELSE 0 END),0) AS BALANCE_diff,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN 1 ELSE 0 END),0) AS PAID_SETTLEMENT_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN ABS(paid_amount-pay_total) ELSE 0 END),0) AS PAID_SETTLEMENT_diff,COALESCE(SUM(CASE WHEN status=4 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN 1 ELSE 0 END),0) AS SETTLED_UNPAID_n,COALESCE(SUM(CASE WHEN status=4 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN ABS(unpaid_amount) ELSE 0 END),0) AS SETTLED_UNPAID_diff,COALESCE(SUM(CASE WHEN duplicates>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicates>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> fee_paid) THEN 1 ELSE 0 END),0) AS PAID_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> fee_paid) THEN ABS(paid_amount-fee_paid) ELSE 0 END),0) AS PAID_DETAILS_diff,COALESCE(SUM(CASE WHEN NOT(unpaid_amount <=> fee_unpaid) THEN 1 ELSE 0 END),0) AS UNPAID_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(unpaid_amount <=> fee_unpaid) THEN ABS(unpaid_amount-fee_unpaid) ELSE 0 END),0) AS UNPAID_DETAILS_diff FROM q LIMIT 1;

