WITH q AS (SELECT p.id,p.serial_no AS business_key,p.tenant_code,p.total_amount,p.paid_amount,p.unpaid_amount,0 AS red_amount,p.status AS status,(SELECT COUNT(*) FROM ol_saps.payment_slip_fee_detail d WHERE d.serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_n,(SELECT COALESCE(SUM(total_amount),0) FROM ol_saps.payment_slip_fee_detail d WHERE d.serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_total,(SELECT COALESCE(SUM(paid_amount),0) FROM ol_saps.payment_slip_fee_detail d WHERE d.serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_paid,(SELECT COALESCE(SUM(unpaid_amount),0) FROM ol_saps.payment_slip_fee_detail d WHERE d.serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_unpaid,(SELECT COALESCE(SUM(pay_amount),0) FROM ol_saps.payment_slip_pay_detail d WHERE d.payment_slip_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS pay_total,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicates FROM ol_saps.payment_slip p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,total_amount,paid_amount,unpaid_amount,red_amount,status,fee_n,fee_total,fee_paid,fee_unpaid,pay_total,duplicates FROM q WHERE (:ruleCode='TOTAL_DETAILS' AND (NOT(total_amount <=> fee_total))) OR (:ruleCode='MISSING_DETAILS' AND (total_amount<>0 AND fee_n=0)) OR (:ruleCode='BALANCE' AND (total_amount IS NULL OR paid_amount IS NULL OR unpaid_amount IS NULL OR NOT(total_amount <=> paid_amount+unpaid_amount+red_amount))) OR (:ruleCode='PAID_SETTLEMENT' AND (NOT(paid_amount <=> pay_total))) OR (:ruleCode='SETTLED_UNPAID' AND (status=4 AND (unpaid_amount IS NULL OR unpaid_amount<>0))) OR (:ruleCode='DUPLICATE_KEY' AND (duplicates>1)) OR (:ruleCode='PAID_DETAILS' AND (NOT(paid_amount <=> fee_paid))) OR (:ruleCode='UNPAID_DETAILS' AND (NOT(unpaid_amount <=> fee_unpaid))) ORDER BY id LIMIT :sampleLimit;

-- 智能柜对账单 [ol_saps_statement]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_saps.statement LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.statement_no AS business_key,p.tenant_code,p.total_amount,p.paid_amount,p.unpaid_amount,COALESCE(p.red_amount,0) AS red_amount,p.status AS status,(SELECT COUNT(*) FROM ol_saps.statement_resource d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_n,(SELECT COALESCE(SUM(fee_amount),0) FROM ol_saps.statement_resource d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS resource_total,(SELECT COUNT(*) FROM ol_saps.statement_fee_detail d WHERE d.statement_no=p.statement_no AND d.is_delete=0 AND d.is_cancel=0) AS fee_detail_n,(SELECT COALESCE(SUM(total_amount),0) FROM ol_saps.statement_fee_detail d WHERE d.statement_no=p.statement_no AND d.is_delete=0 AND d.is_cancel=0) AS fee_detail_total,NULL AS fee_paid,NULL AS fee_unpaid,(SELECT COALESCE(SUM(trans_amount),0) FROM ol_saps.statement_pay_detail d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS pay_total,(SELECT COUNT(*) FROM ol_saps.statement d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicates FROM ol_saps.statement p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(total_amount <=> CASE WHEN fee_detail_n>0 THEN fee_detail_total ELSE resource_total END) THEN 1 ELSE 0 END),0) AS TOTAL_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(total_amount <=> CASE WHEN fee_detail_n>0 THEN fee_detail_total ELSE resource_total END) THEN ABS(total_amount-CASE WHEN fee_detail_n>0 THEN fee_detail_total ELSE resource_total END) ELSE 0 END),0) AS TOTAL_DETAILS_diff,COALESCE(SUM(CASE WHEN total_amount<>0 AND fee_n=0 THEN 1 ELSE 0 END),0) AS MISSING_DETAILS_n,COALESCE(SUM(CASE WHEN total_amount<>0 AND fee_n=0 THEN ABS(total_amount) ELSE 0 END),0) AS MISSING_DETAILS_diff,COALESCE(SUM(CASE WHEN ROUND(total_amount,2) <> ROUND(paid_amount+unpaid_amount+red_amount,2) THEN 1 ELSE 0 END),0) AS BALANCE_n,COALESCE(SUM(CASE WHEN ROUND(total_amount,2) <> ROUND(paid_amount+unpaid_amount+red_amount,2) THEN ABS(ROUND(total_amount,2)-ROUND(paid_amount+unpaid_amount+red_amount,2)) ELSE 0 END),0) AS BALANCE_diff,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN 1 ELSE 0 END),0) AS PAID_SETTLEMENT_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> pay_total) THEN ABS(paid_amount-pay_total) ELSE 0 END),0) AS PAID_SETTLEMENT_diff,COALESCE(SUM(CASE WHEN status=1 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN 1 ELSE 0 END),0) AS SETTLED_UNPAID_n,COALESCE(SUM(CASE WHEN status=1 AND (unpaid_amount IS NULL OR unpaid_amount<>0) THEN ABS(unpaid_amount) ELSE 0 END),0) AS SETTLED_UNPAID_diff,COALESCE(SUM(CASE WHEN duplicates>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicates>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.statement_no AS business_key,p.tenant_code,p.total_amount,p.paid_amount,p.unpaid_amount,COALESCE(p.red_amount,0) AS red_amount,p.status AS status,(SELECT COUNT(*) FROM ol_saps.statement_resource d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS fee_n,(SELECT COALESCE(SUM(fee_amount),0) FROM ol_saps.statement_resource d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS resource_total,(SELECT COUNT(*) FROM ol_saps.statement_fee_detail d WHERE d.statement_no=p.statement_no AND d.is_delete=0 AND d.is_cancel=0) AS fee_detail_n,(SELECT COALESCE(SUM(total_amount),0) FROM ol_saps.statement_fee_detail d WHERE d.statement_no=p.statement_no AND d.is_delete=0 AND d.is_cancel=0) AS fee_detail_total,NULL AS fee_paid,NULL AS fee_unpaid,(SELECT COALESCE(SUM(trans_amount),0) FROM ol_saps.statement_pay_detail d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS pay_total,(SELECT COUNT(*) FROM ol_saps.statement d WHERE d.statement_no=p.statement_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicates FROM ol_saps.statement p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,total_amount,paid_amount,unpaid_amount,red_amount,status,fee_n,resource_total,fee_detail_n,fee_detail_total,fee_paid,fee_unpaid,pay_total,duplicates FROM q WHERE (:ruleCode='TOTAL_DETAILS' AND (NOT(total_amount <=> CASE WHEN fee_detail_n>0 THEN fee_detail_total ELSE resource_total END))) OR (:ruleCode='MISSING_DETAILS' AND (total_amount<>0 AND fee_n=0)) OR (:ruleCode='BALANCE' AND (ROUND(total_amount,2) <> ROUND(paid_amount+unpaid_amount+red_amount,2))) OR (:ruleCode='PAID_SETTLEMENT' AND (NOT(paid_amount <=> pay_total))) OR (:ruleCode='SETTLED_UNPAID' AND (status=1 AND (unpaid_amount IS NULL OR unpaid_amount<>0))) OR (:ruleCode='DUPLICATE_KEY' AND (duplicates>1)) ORDER BY id LIMIT :sampleLimit;

-- 叉车客户支付订单 [lease_saps_order]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM lease_saps.customer_order LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.order_no AS business_key,p.status,p.sub_type,p.transaction_mode,p.pay_amount,p.transaction_amount,p.settle_amount,p.recharge_amount,p.discount_amount,(SELECT COUNT(*) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_n,(SELECT COALESCE(SUM(pay_amount),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_requested,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN transaction_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_actual,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN settle_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_settle,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN recharge_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_recharge,(SELECT COUNT(*) FROM lease_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicates FROM lease_saps.customer_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN detail_n=0 THEN 1 ELSE 0 END),0) AS MISSING_TRANSACTION_n,COALESCE(SUM(CASE WHEN detail_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_TRANSACTION_diff,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> detail_requested) THEN 1 ELSE 0 END),0) AS REQUESTED_DETAILS_n,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> detail_requested) THEN ABS(pay_amount-detail_requested) ELSE 0 END),0) AS REQUESTED_DETAILS_diff,COALESCE(SUM(CASE WHEN status=4 AND NOT(transaction_amount <=> detail_actual) THEN 1 ELSE 0 END),0) AS ACTUAL_DETAILS_n,COALESCE(SUM(CASE WHEN status=4 AND NOT(transaction_amount <=> detail_actual) THEN ABS(transaction_amount-detail_actual) ELSE 0 END),0) AS ACTUAL_DETAILS_diff,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> detail_settle) THEN 1 ELSE 0 END),0) AS SETTLE_DETAILS_n,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> detail_settle) THEN ABS(settle_amount-detail_settle) ELSE 0 END),0) AS SETTLE_DETAILS_diff,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(recharge_amount <=> detail_recharge) THEN 1 ELSE 0 END),0) AS RECHARGE_DETAILS_n,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(recharge_amount <=> detail_recharge) THEN ABS(recharge_amount-detail_recharge) ELSE 0 END),0) AS RECHARGE_DETAILS_diff,COALESCE(SUM(CASE WHEN duplicates>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicates>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.order_no AS business_key,p.status,p.sub_type,p.transaction_mode,p.pay_amount,p.transaction_amount,p.settle_amount,p.recharge_amount,p.discount_amount,(SELECT COUNT(*) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_n,(SELECT COALESCE(SUM(pay_amount),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_requested,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN transaction_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_actual,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN settle_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_settle,(SELECT COALESCE(SUM(CASE WHEN status=4 THEN recharge_amount ELSE 0 END),0) FROM lease_saps.customer_transaction d WHERE d.order_no=p.order_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_recharge,(SELECT COUNT(*) FROM lease_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicates FROM lease_saps.customer_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,status,sub_type,transaction_mode,pay_amount,transaction_amount,settle_amount,recharge_amount,discount_amount,detail_n,detail_requested,detail_actual,detail_settle,detail_recharge FROM q WHERE (:ruleCode='MISSING_TRANSACTION' AND (detail_n=0)) OR (:ruleCode='REQUESTED_DETAILS' AND (NOT(pay_amount <=> detail_requested))) OR (:ruleCode='ACTUAL_DETAILS' AND (status=4 AND NOT(transaction_amount <=> detail_actual))) OR (:ruleCode='SETTLE_DETAILS' AND (status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> detail_settle))) OR (:ruleCode='RECHARGE_DETAILS' AND (status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(recharge_amount <=> detail_recharge))) OR (:ruleCode='DUPLICATE_KEY' AND (duplicates>1)) ORDER BY id LIMIT :sampleLimit;

