ay_amount) ELSE 0 END),0) AS MISSING_TRANSACTION_diff,COALESCE(SUM(CASE WHEN sub_type NOT IN (3003,3004,3005) AND (NOT(pay_amount <=> detail_requested)) THEN 1 ELSE 0 END),0) AS REQUESTED_DETAILS_n,COALESCE(SUM(CASE WHEN sub_type NOT IN (3003,3004,3005) AND (NOT(pay_amount <=> detail_requested)) THEN ABS(pay_amount-detail_requested) ELSE 0 END),0) AS REQUESTED_DETAILS_diff,COALESCE(SUM(CASE WHEN sub_type NOT IN (3003,3004,3005) AND (status=4 AND NOT(transaction_amount <=> detail_actual)) THEN 1 ELSE 0 END),0) AS ACTUAL_DETAILS_n,COALESCE(SUM(CASE WHEN sub_type NOT IN (3003,3004,3005) AND (status=4 AND NOT(transaction_amount <=> detail_actual)) THEN ABS(transaction_amount-detail_actual) ELSE 0 END),0) AS ACTUAL_DETAILS_diff,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> detail_settle) THEN 1 ELSE 0 END),0) AS SETTLE_DETAILS_n,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> detail_settle) THEN ABS(settle_amount-detail_settle) ELSE 0 END),0) AS SETTLE_DETAILS_diff,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(recharge_amount <=> detail_recharge) THEN 1 ELSE 0 END),0) AS RECHARGE_DETAILS_n,COALESCE(SUM(CASE WHEN status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(recharge_amount <=> detail_recharge) THEN ABS(recharge_amount-detail_recharge) ELSE 0 END),0) AS RECHARGE_DETAILS_diff,COALESCE(SUM(CASE WHEN duplicates>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicates>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff FROM q LIMIT 1;

