RANSACTION' AND (sub_type NOT IN (3003,3004,3005) AND (detail_n=0))) OR (:ruleCode='REQUESTED_DETAILS' AND (sub_type NOT IN (3003,3004,3005) AND (NOT(pay_amount <=> detail_requested)))) OR (:ruleCode='ACTUAL_DETAILS' AND (sub_type NOT IN (3003,3004,3005) AND (status=4 AND NOT(transaction_amount <=> detail_actual)))) OR (:ruleCode='SETTLE_DETAILS' AND (status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> detail_settle))) OR (:ruleCode='RECHARGE_DETAILS' AND (status=4 AND sub_type IN (2000,2001,2002,2100,3006) AND NOT(recharge_amount <=> detail_recharge))) OR (:ruleCode='DUPLICATE_KEY' AND (duplicates>1)) ORDER BY id LIMIT :sampleLimit;

-- 叉车账单结算明细 [lease_saps_bill_settlement]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM lease_saps.customer_bill_pay_detail LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.bill_no AS document_no,p.order_no,p.trans_no,p.pay_amount,p.is_reverse,(SELECT COALESCE(SUM(d.paid_amount),0) FROM lease_saps.customer_bill_pay_subject_detail d WHERE d.pay_detail_serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS subject_total,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS parent_n,(SELECT COUNT(*) FROM lease_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS order_n,(SELECT COUNT(*) FROM lease_saps.customer_transaction d WHERE d.serial_no=p.trans_no AND d.order_no=p.order_no AND d.status=4 AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS transaction_n FROM lease_saps.customer_bill_pay_detail p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> subject_total) THEN 1 ELSE 0 END),0) AS SUBJECT_SUM_n,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> subject_total) THEN ABS(pay_amount-subject_total) ELSE 0 END),0) AS SUBJECT_SUM_diff,COALESCE(SUM(CASE WHEN parent_n=0 THEN 1 ELSE 0 END),0) AS MISSING_PARENT_n,COALESCE(SUM(CASE WHEN parent_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_PARENT_diff,COALESCE(SUM(CASE WHEN order_n=0 THEN 1 ELSE 0 END),0) AS MISSING_ORDER_n,COALESCE(SUM(CASE WHEN order_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_ORDER_diff,COALESCE(SUM(CASE WHEN transaction_n=0 THEN 1 ELSE 0 END),0) AS MISSING_SUCCESS_TRANSACTION_n,COALESCE(SUM(CASE WHEN transaction_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_SUCCESS_TRANSACTION_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.bill_no AS document_no,p.order_no,p.trans_no,p.pay_amount,p.is_reverse,(SELECT COALESCE(SUM(d.paid_amount),0) FROM lease_saps.customer_bill_pay_subject_detail d WHERE d.pay_detail_serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS subject_total,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS parent_n,(SELECT COUNT(*) FROM lease_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS order_n,(SELECT COUNT(*) FROM lease_saps.customer_transaction d WHERE d.serial_no=p.trans_no AND d.order_no=p.order_no AND d.status=4 AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS transaction_n FROM lease_saps.customer_bill_pay_detail p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,document_no,order_no,trans_no,pay_amount,is_reverse,subject_total,parent_n,order_n,transaction_n FROM q WHERE (:ruleCode='SUBJECT_SUM' AND (NOT(pay_amount <=> subject_total))) OR (:ruleCode='MISSING_PARENT' AND (parent_n=0)) OR (:ruleCode='MISSING_ORDER' AND (order_n=0)) OR (:ruleCode='MISSING_SUCCESS_TRANSACTION' AND (transaction_n=0)) ORDER BY id LIMIT :sampleLimit;

