SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_saps.customer_bill_pay_detail LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.bill_no AS document_no,p.order_no,p.trans_no,p.pay_amount,p.is_reverse,(SELECT COALESCE(SUM(d.paid_amount),0) FROM ol_saps.customer_bill_pay_subject_detail d WHERE d.pay_detail_serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS subject_total,(SELECT COUNT(*) FROM ol_saps.customer_bill d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS parent_n,(SELECT COUNT(*) FROM ol_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS order_n,(SELECT COUNT(*) FROM ol_saps.customer_transaction d WHERE d.serial_no=p.trans_no AND d.order_no=p.order_no AND d.status=4 AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS transaction_n FROM ol_saps.customer_bill_pay_detail p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> subject_total) THEN 1 ELSE 0 END),0) AS SUBJECT_SUM_n,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> subject_total) THEN ABS(pay_amount-subject_total) ELSE 0 END),0) AS SUBJECT_SUM_diff,COALESCE(SUM(CASE WHEN parent_n=0 THEN 1 ELSE 0 END),0) AS MISSING_PARENT_n,COALESCE(SUM(CASE WHEN parent_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_PARENT_diff,COALESCE(SUM(CASE WHEN order_n=0 THEN 1 ELSE 0 END),0) AS MISSING_ORDER_n,COALESCE(SUM(CASE WHEN order_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_ORDER_diff,COALESCE(SUM(CASE WHEN transaction_n=0 THEN 1 ELSE 0 END),0) AS MISSING_SUCCESS_TRANSACTION_n,COALESCE(SUM(CASE WHEN transaction_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_SUCCESS_TRANSACTION_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.bill_no AS document_no,p.order_no,p.trans_no,p.pay_amount,p.is_reverse,(SELECT COALESCE(SUM(d.paid_amount),0) FROM ol_saps.customer_bill_pay_subject_detail d WHERE d.pay_detail_serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS subject_total,(SELECT COUNT(*) FROM ol_saps.customer_bill d WHERE d.bill_no=p.bill_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS parent_n,(SELECT COUNT(*) FROM ol_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS order_n,(SELECT COUNT(*) FROM ol_saps.customer_transaction d WHERE d.serial_no=p.trans_no AND d.order_no=p.order_no AND d.status=4 AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS transaction_n FROM ol_saps.customer_bill_pay_detail p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,document_no,order_no,trans_no,pay_amount,is_reverse,subject_total,parent_n,order_n,transaction_n FROM q WHERE (:ruleCode='SUBJECT_SUM' AND (NOT(pay_amount <=> subject_total))) OR (:ruleCode='MISSING_PARENT' AND (parent_n=0)) OR (:ruleCode='MISSING_ORDER' AND (order_n=0)) OR (:ruleCode='MISSING_SUCCESS_TRANSACTION' AND (transaction_n=0)) ORDER BY id LIMIT :sampleLimit;

-- 智能柜缴费单结算明细 [ol_saps_slip_settlement]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_saps.payment_slip_pay_detail LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.payment_slip_no AS document_no,p.order_no,p.trans_no,p.pay_amount,p.is_reverse,(SELECT COALESCE(SUM(d.pay_amount),0) FROM ol_saps.payment_slip_pay_subject_detail d WHERE d.pay_detail_serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS subject_total,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=p.payment_slip_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS parent_n,(SELECT COUNT(*) FROM ol_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS order_n,(SELECT COUNT(*) FROM ol_saps.customer_transaction d WHERE d.serial_no=p.trans_no AND d.order_no=p.order_no AND d.status=4 AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS transaction_n FROM ol_saps.payment_slip_pay_detail p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> subject_total) THEN 1 ELSE 0 END),0) AS SUBJECT_SUM_n,COALESCE(SUM(CASE WHEN NOT(pay_amount <=> subject_total) THEN ABS(pay_amount-subject_total) ELSE 0 END),0) AS SUBJECT_SUM_diff,COALESCE(SUM(CASE WHEN parent_n=0 THEN 1 ELSE 0 END),0) AS MISSING_PARENT_n,COALESCE(SUM(CASE WHEN parent_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_PARENT_diff,COALESCE(SUM(CASE WHEN order_n=0 THEN 1 ELSE 0 END),0) AS MISSING_ORDER_n,COALESCE(SUM(CASE WHEN order_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_ORDER_diff,COALESCE(SUM(CASE WHEN transaction_n=0 THEN 1 ELSE 0 END),0) AS MISSING_SUCCESS_TRANSACTION_n,COALESCE(SUM(CASE WHEN transaction_n=0 THEN ABS(pay_amount) ELSE 0 END),0) AS MISSING_SUCCESS_TRANSACTION_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.payment_slip_no AS document_no,p.order_no,p.trans_no,p.pay_amount,p.is_reverse,(SELECT COALESCE(SUM(d.pay_amount),0) FROM ol_saps.payment_slip_pay_subject_detail d WHERE d.pay_detail_serial_no=p.serial_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS subject_total,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=p.payment_slip_no AND d.tenant_code <=> p.tenant_code AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS parent_n,(SELECT COUNT(*) FROM ol_saps.customer_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS order_n,(SELECT COUNT(*) FROM ol_saps.customer_transaction d WHERE d.serial_no=p.trans_no AND d.order_no=p.order_no AND d.status=4 AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS transaction_n FROM ol_saps.payment_slip_pay_detail p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,document_no,order_no,trans_no,pay_amount,is_reverse,subject_total,parent_n,order_n,transaction_n FROM q WHERE (:ruleCode='SUBJECT_SUM' AND (NOT(pay_amount <=> subject_total))) OR (:ruleCode='MISSING_PARENT' AND (parent_n=0)) OR (:ruleCode='MISSING_ORDER' AND (order_n=0)) OR (:ruleCode='MISSING_SUCCESS_TRANSACTION' AND (transaction_n=0)) ORDER BY id LIMIT :sampleLimit;

-- 智能柜付款单 [ol_order_payable]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_order.payment_order LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.order_no AS business_key,p.order_status,p.amount,p.paid_amount,p.purchase_order_no,p.batch_no,(SELECT COALESCE(SUM(d.pay_amount),0) FROM ol_order.payment_order_paydetail d WHERE d.pay_order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_paid,(SELECT COUNT(*) FROM ol_order.payment_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicate_n,(SELECT COUNT(*) FROM ol_order.purchase_order d WHERE d.order_no=p.purchase_order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS source_n,(SELECT MIN(d.purchase_price) FROM ol_order.purchase_order d WHERE d.order_no=p.purchase_order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS source_amount FROM ol_order.payment_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> detail_paid) THEN 1 ELSE 0 END),0) AS PAID_DETAIL_n,COALESCE(SUM(CASE WHEN NOT(paid_amount <=> detail_paid) THEN ABS(paid_amount-detail_paid) ELSE 0 END),0) AS PAID_DETAIL_diff,COALESCE(SUM(CASE WHEN order_status='paid' AND NOT(amount <=> paid_amount) THEN 1 ELSE 0 END),0) AS PAID_STATUS_n,COALESCE(SUM(CASE WHEN order_status='paid' AND NOT(amount <=> paid_amount) THEN ABS(amount-paid_amount) ELSE 0 END),0) AS PAID_STATUS_diff,COALESCE(SUM(CASE WHEN duplicate_n>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicate_n>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff,COALESCE(SUM(CASE WHEN source_n=0 THEN 1 ELSE 0 END),0) AS SOURCE_MISSING_n,COALESCE(SUM(CASE WHEN source_n=0 THEN ABS(amount) ELSE 0 END),0) AS SOURCE_MISSING_diff,COALESCE(SUM(CASE WHEN COALESCE(batch_no,'')='' AND NOT(amount <=> source_amount) THEN 1 ELSE 0 END),0) AS SOURCE_AMOUNT_n,COALESCE(SUM(CASE WHEN COALESCE(batch_no,'')='' AND NOT(amount <=> source_amount) THEN ABS(amount-source_amount) ELSE 0 END),0) AS SOURCE_AMOUNT_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.order_no AS business_key,p.order_status,p.amount,p.paid_amount,p.purchase_order_no,p.batch_no,(SELECT COALESCE(SUM(d.pay_amount),0) FROM ol_order.payment_order_paydetail d WHERE d.pay_order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS detail_paid,(SELECT COUNT(*) FROM ol_order.payment_order d WHERE d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicate_n,(SELECT COUNT(*) FROM ol_order.purchase_order d WHERE d.order_no=p.purchase_order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS source_n,(SELECT MIN(d.purchase_price) FROM ol_order.purchase_order d WHERE d.order_no=p.purchase_order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS source_amount FROM ol_order.payment_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,order_status,amount,paid_amount,detail_paid,purchase_order_no,batch_no,source_n,source_amount FROM q WHERE (:ruleCode='PAID_DETAIL' AND (NOT(paid_amount <=> detail_paid))) OR (:ruleCode='PAID_STATUS' AND (order_status='paid' AND NOT(amount <=> paid_amount))) OR (:ruleCode='DUPLICATE_KEY' AND (duplicate_n>1)) OR (:ruleCode='SOURCE_MISSING' AND (source_n=0)) OR (:ruleCode='SOURCE_AMOUNT' AND (COALESCE(batch_no,'')='' AND NOT(amount <=> source_amount))) ORDER BY id LIMIT :sampleLimit;

-- 叉车付款单 [lease_finance_payable]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM lease_finance.payment_order LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.payment_no AS business_key,p.status,p.payment_result,p.amount,p.pay_amount,p.payment_serial_no,(SELECT COUNT(*) FROM lease_finance.payment_order d WHERE d.payment_no=p.payment_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicate_n FROM lease_finance.payment_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN status=40 AND NOT(amount <=> pay_amount) THEN 1 ELSE 0 END),0) AS PAID_STATUS_n,COALESCE(SUM(CASE WHEN status=40 AND NOT(amount <=> pay_amount) THEN ABS(amount-pay_amount) ELSE 0 END),0) AS PAID_STATUS_diff,COALESCE(SUM(CASE WHEN duplicate_n>1 THEN 1 ELSE 0 END),0) AS DUPLICATE_KEY_n,COALESCE(SUM(CASE WHEN duplicate_n>1 THEN ABS(0) ELSE 0 END),0) AS DUPLICATE_KEY_diff,COALESCE(SUM(CASE WHEN status=40 AND NOT(payment_result <=> 4) THEN 1 ELSE 0 END),0) AS PAYMENT_STATE_n,COALESCE(SUM(CASE WHEN status=40 AND NOT(payment_result <=> 4) THEN ABS(0) ELSE 0 END),0) AS PAYMENT_STATE_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.payment_no AS business_key,p.status,p.payment_result,p.amount,p.pay_amount,p.payment_serial_no,(SELECT COUNT(*) FROM lease_finance.payment_order d WHERE d.payment_no=p.payment_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS duplicate_n FROM lease_finance.payment_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,status,payment_result,amount,pay_amount,payment_serial_no,duplicate_n FROM q WHERE (:ruleCode='PAID_STATUS' AND (status=40 AND NOT(amount <=> pay_amount))) OR (:ruleCode='DUPLICATE_KEY' AND (duplicate_n>1)) OR (:ruleCode='PAYMENT_STATE' AND (status=40 AND NOT(payment_result <=> 4))) ORDER BY id LIMIT :sampleLimit;

-- 叉车支付中台及渠道 [lease_saps_channel]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id,(SELECT COALESCE(MAX(id),0) FROM lease_payment.order_channel) AS legacy_max_id FROM lease_saps.customer_order LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH legacy_c AS (SELECT order_business_no,SUM(CASE WHEN status=4 THEN transaction_amount ELSE 0 END) AS actual_amount,SUM(status=4) AS success_n,MIN(CASE WHEN status=4 THEN channel END) AS success_channel FROM lease_payment.order_channel c WHERE c.id BETWEEN 1 AND :legacyMaxId AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0 GROUP BY order_business_no),q AS (SELECT p.id,p.order_no AS business_key,p.status,p.sub_type,p.channel,p.pay_serial_no,p.transaction_amount,COALESCE(b.serial_no,l.serial_no) AS middle_no,COALESCE(b.status,l.status) AS middle_status,COALESCE(b.transaction_amount,l.transaction_amount) AS middle_amount,CASE WHEN b.id IS NOT NULL THEN 'xxt_pay' ELSE 'lease_payment' END AS route,CASE WHEN b.id IS NOT NULL THEN (SELECT COALESCE(SUM(CASE WHEN status IN ('4','SUCCESS','PARTIAL') THEN transaction_amount ELSE 0 END),0) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE COALESCE(lc.actual_amount,0) END AS channel_actual,CASE WHEN b.id IS NOT NULL THEN (SELECT COALESCE(SUM(status IN ('4','SUCCESS','PARTIAL')),0) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE COALESCE(lc.success_n,0) END AS channel_success_n,CASE WHEN b.id IS NOT NULL THEN (SELECT MIN(CASE WHEN status IN ('4','SUCCESS','PARTIAL') THEN channel END) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE lc.success_channel END AS success_channel FROM lease_saps.customer_order p LEFT JOIN xxt_pay.order_business b ON b.merchant_sn=p.order_no COLLATE utf8mb4_0900_ai_ci AND COALESCE(b.is_delete,0)=0 AND COALESCE(b.is_cancel,0)=0 LEFT JOIN lease_payment.order_business l ON l.biz_serial_no=CONVERT(p.order_no USING utf8) COLLATE utf8_general_ci AND l.biz_system=1 AND l.customer_code=CONVERT(p.customer_code USING utf8) COLLATE utf8_general_ci AND COALESCE(l.is_delete,0)=0 AND COALESCE(l.is_cancel,0)=0 LEFT JOIN legacy_c lc ON lc.order_business_no=CONVERT(l.serial_no USING utf8mb4) COLLATE utf8mb4_general_ci WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND p.transaction_mode=1 AND p.sub_type IN (1000,1001,2000,2001,2002,2100,2200,2201) AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NULL THEN 1 ELSE 0 END),0) AS MID_MISSING_n,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NULL THEN ABS(transaction_amount) ELSE 0 END),0) AS MID_MISSING_diff,COALESCE(SUM(CASE WHEN middle_no IS NOT NULL AND ((status=4 AND middle_status<>4) OR (status<>4 AND middle_status=4)) THEN 1 ELSE 0 END),0) AS MID_STATUS_n,COALESCE(SUM(CASE WHEN middle_no IS NOT NULL AND ((status=4 AND middle_status<>4) OR (status<>4 AND middle_status=4)) THEN ABS(0) ELSE 0 END),0) AS MID_STATUS_diff,COALESCE(SUM(CASE WHEN status=4 AND middle_status=4 AND NOT(transaction_amount <=> middle_amount) THEN 1 ELSE 0 END),0) AS MID_AMOUNT_n,COALESCE(SUM(CASE WHEN status=4 AND middle_status=4 AND NOT(transaction_amount <=> middle_amount) THEN ABS(transaction_amount-middle_amount) ELSE 0 END),0) AS MID_AMOUNT_diff,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NOT NULL AND pay_serial_no IS NOT NULL AND pay_serial_no COLLATE utf8mb4_0900_ai_ci<>CONVERT(middle_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci THEN 1 ELSE 0 END),0) AS MID_LINK_n,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NOT NULL AND pay_serial_no IS NOT NULL AND pay_serial_no COLLATE utf8mb4_0900_ai_ci<>CONVERT(middle_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci THEN ABS(0) ELSE 0 END),0) AS MID_LINK_diff,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n=0 THEN 1 ELSE 0 END),0) AS CHANNEL_MISSING_n,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n=0 THEN ABS(middle_amount) ELSE 0 END),0) AS CHANNEL_MISSING_diff,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n>0 AND NOT(middle_amount <=> channel_actual) THEN 1 ELSE 0 END),0) AS CHANNEL_AMOUNT_n,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n>0 AND NOT(middle_amount <=> channel_actual) THEN ABS(middle_amount-channel_actual) ELSE 0 END),0) AS CHANNEL_AMOUNT_diff,COALESCE(SUM(CASE WHEN status=4 AND channel_success_n=1 AND NOT(channel <=> success_channel) THEN 1 ELSE 0 END),0) AS CHANNEL_CODE_n,COALESCE(SUM(CASE WHEN status=4 AND channel_success_n=1 AND NOT(channel <=> success_channel) THEN ABS(0) ELSE 0 END),0) AS CHANNEL_CODE_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH legacy_c AS (SELECT order_business_no,SUM(CASE WHEN status=4 THEN transaction_amount ELSE 0 END) AS actual_amount,SUM(status=4) AS success_n,MIN(CASE WHEN status=4 THEN channel END) AS success_channel FROM lease_payment.order_channel c WHERE c.id BETWEEN 1 AND :legacyMaxId AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0 GROUP BY order_business_no),q AS (SELECT p.id,p.order_no AS business_key,p.status,p.sub_type,p.channel,p.pay_serial_no,p.transaction_amount,COALESCE(b.serial_no,l.serial_no) AS middle_no,COALESCE(b.status,l.status) AS middle_status,COALESCE(b.transaction_amount,l.transaction_amount) AS middle_amount,CASE WHEN b.id IS NOT NULL THEN 'xxt_pay' ELSE 'lease_payment' END AS route,CASE WHEN b.id IS NOT NULL THEN (SELECT COALESCE(SUM(CASE WHEN status IN ('4','SUCCESS','PARTIAL') THEN transaction_amount ELSE 0 END),0) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE COALESCE(lc.actual_amount,0) END AS channel_actual,CASE WHEN b.id IS NOT NULL THEN (SELECT COALESCE(SUM(status IN ('4','SUCCESS','PARTIAL')),0) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE COALESCE(lc.success_n,0) END AS channel_success_n,CASE WHEN b.id IS NOT NULL THEN (SELECT MIN(CASE WHEN status IN ('4','SUCCESS','PARTIAL') THEN channel END) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE lc.success_channel END AS success_channel FROM lease_saps.customer_order p LEFT JOIN xxt_pay.order_business b ON b.merchant_sn=p.order_no COLLATE utf8mb4_0900_ai_ci AND COALESCE(b.is_delete,0)=0 AND COALESCE(b.is_cancel,0)=0 LEFT JOIN lease_payment.order_business l ON l.biz_serial_no=CONVERT(p.order_no USING utf8) COLLATE utf8_general_ci AND l.biz_system=1 AND l.customer_code=CONVERT(p.customer_code USING utf8) COLLATE utf8_general_ci AND COALESCE(l.is_delete,0)=0 AND COALESCE(l.is_cancel,0)=0 LEFT JOIN legacy_c lc ON lc.order_business_no=CONVERT(l.serial_no USING utf8mb4) COLLATE utf8mb4_general_ci WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND p.transaction_mode=1 AND p.sub_type IN (1000,1001,2000,2001,2002,2100,2200,2201) AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,status,sub_type,channel,pay_serial_no,transaction_amount,middle_no,middle_status,middle_amount,route,channel_actual,channel_success_n,success_channel FROM q WHERE (:ruleCode='MID_MISSING' AND (status=4 AND middle_no IS NULL)) OR (:ruleCode='MID_STATUS' AND (middle_no IS NOT NULL AND ((status=4 AND middle_status<>4) OR (status<>4 AND middle_status=4)))) OR (:ruleCode='MID_AMOUNT' AND (status=4 AND middle_status=4 AND NOT(transaction_amount <=> middle_amount))) OR (:ruleCode='MID_LINK' AND (status=4 AND middle_no IS NOT NULL AND pay_serial_no IS NOT NULL AND pay_serial_no COLLATE utf8mb4_0900_ai_ci<>CONVERT(middle_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci)) OR (:ruleCode='CHANNEL_MISSING' AND (middle_status=4 AND channel_success_n=0)) OR (:ruleCode='CHANNEL_AMOUNT' AND (middle_status=4 AND channel_success_n>0 AND NOT(middle_amount <=> channel_actual))) OR (:ruleCode='CHANNEL_CODE' AND (status=4 AND channel_success_n=1 AND NOT(channel <=> success_channel))) ORDER BY id LIMIT :sampleLimit;

