-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH legacy_c AS (SELECT order_business_no,SUM(CASE WHEN status=4 THEN transaction_amount ELSE 0 END) AS actual_amount,SUM(status=4) AS success_n,MIN(CASE WHEN status=4 THEN channel END) AS success_channel FROM ol_payment.order_channel c WHERE c.id BETWEEN 1 AND :legacyMaxId AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0 GROUP BY order_business_no),q AS (SELECT p.id,p.order_no AS business_key,p.status,p.sub_type,p.channel,p.pay_serial_no,p.transaction_amount,COALESCE(b.serial_no,l.serial_no) AS middle_no,COALESCE(b.status,l.status) AS middle_status,COALESCE(b.transaction_amount,l.transaction_amount) AS middle_amount,CASE WHEN b.id IS NOT NULL THEN 'xxt_pay' ELSE 'ol_payment' END AS route,CASE WHEN b.id IS NOT NULL THEN (SELECT COALESCE(SUM(CASE WHEN status IN ('4','SUCCESS','PARTIAL') THEN transaction_amount ELSE 0 END),0) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE COALESCE(lc.actual_amount,0) END AS channel_actual,CASE WHEN b.id IS NOT NULL THEN (SELECT COALESCE(SUM(status IN ('4','SUCCESS','PARTIAL')),0) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE COALESCE(lc.success_n,0) END AS channel_success_n,CASE WHEN b.id IS NOT NULL THEN (SELECT MIN(CASE WHEN status IN ('4','SUCCESS','PARTIAL') THEN channel END) FROM xxt_pay.order_channel c WHERE c.order_business_sn=b.serial_no AND COALESCE(c.is_delete,0)=0 AND COALESCE(c.is_cancel,0)=0) ELSE lc.success_channel END AS success_channel FROM ol_saps.customer_order p LEFT JOIN xxt_pay.order_business b ON b.merchant_sn=p.order_no COLLATE utf8mb4_0900_ai_ci AND COALESCE(b.is_delete,0)=0 AND COALESCE(b.is_cancel,0)=0 LEFT JOIN ol_payment.order_business l ON l.biz_serial_no=CONVERT(p.order_no USING utf8) COLLATE utf8_general_ci AND l.biz_system=1 AND l.customer_code=CONVERT(p.customer_code USING utf8) COLLATE utf8_general_ci AND COALESCE(l.is_delete,0)=0 AND COALESCE(l.is_cancel,0)=0 LEFT JOIN legacy_c lc ON lc.order_business_no=CONVERT(l.serial_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND p.transaction_mode=1 AND p.sub_type IN (1000,1001,2000,2001,2002,2100,2200,2201) AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NULL THEN 1 ELSE 0 END),0) AS MID_MISSING_n,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NULL THEN ABS(transaction_amount) ELSE 0 END),0) AS MID_MISSING_diff,COALESCE(SUM(CASE WHEN middle_no IS NOT NULL AND ((status=4 AND middle_status<>4) OR (status<>4 AND middle_status=4)) THEN 1 ELSE 0 END),0) AS MID_STATUS_n,COALESCE(SUM(CASE WHEN middle_no IS NOT NULL AND ((status=4 AND middle_status<>4) OR (status<>4 AND middle_status=4)) THEN ABS(0) ELSE 0 END),0) AS MID_STATUS_diff,COALESCE(SUM(CASE WHEN status=4 AND middle_status=4 AND NOT(transaction_amount <=> middle_amount) THEN 1 ELSE 0 END),0) AS MID_AMOUNT_n,COALESCE(SUM(CASE WHEN status=4 AND middle_status=4 AND NOT(transaction_amount <=> middle_amount) THEN ABS(transaction_amount-middle_amount) ELSE 0 END),0) AS MID_AMOUNT_diff,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NOT NULL AND pay_serial_no IS NOT NULL AND pay_serial_no COLLATE utf8mb4_0900_ai_ci<>CONVERT(middle_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci THEN 1 ELSE 0 END),0) AS MID_LINK_n,COALESCE(SUM(CASE WHEN status=4 AND middle_no IS NOT NULL AND pay_serial_no IS NOT NULL AND pay_serial_no COLLATE utf8mb4_0900_ai_ci<>CONVERT(middle_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci THEN ABS(0) ELSE 0 END),0) AS MID_LINK_diff,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n=0 THEN 1 ELSE 0 END),0) AS CHANNEL_MISSING_n,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n=0 THEN ABS(middle_amount) ELSE 0 END),0) AS CHANNEL_MISSING_diff,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n>0 AND NOT(middle_amount <=> channel_actual) THEN 1 ELSE 0 END),0) AS CHANNEL_AMOUNT_n,COALESCE(SUM(CASE WHEN middle_status=4 AND channel_success_n>0 AND NOT(middle_amount <=> channel_actual) THEN ABS(middle_amount-channel_actual) ELSE 0 END),0) AS CHANNEL_AMOUNT_diff,COALESCE(SUM(CASE WHEN status=4 AND channel_success_n=1 AND NOT(channel <=> success_channel) THEN 1 ELSE 0 END),0) AS CHANNEL_CODE_n,COALESCE(SUM(CASE WHEN status=4 AND channel_success_n=1 AND NOT(channel <=> success_channel) THEN ABS(0) ELSE 0 END),0) AS CHANNEL_CODE_diff FROM q LIMIT 1;

