delete,0)=0 AND COALESCE(l.is_cancel,0)=0 LEFT JOIN legacy_c lc ON lc.order_business_no=CONVERT(l.serial_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND p.transaction_mode=1 AND p.sub_type IN (1000,1001,2000,2001,2002,2100,2200,2201) AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,status,sub_type,channel,pay_serial_no,transaction_amount,middle_no,middle_status,middle_amount,route,channel_actual,channel_success_n,success_channel FROM q WHERE (:ruleCode='MID_MISSING' AND (status=4 AND middle_no IS NULL)) OR (:ruleCode='MID_STATUS' AND (middle_no IS NOT NULL AND ((status=4 AND middle_status<>4) OR (status<>4 AND middle_status=4)))) OR (:ruleCode='MID_AMOUNT' AND (status=4 AND middle_status=4 AND NOT(transaction_amount <=> middle_amount))) OR (:ruleCode='MID_LINK' AND (status=4 AND middle_no IS NOT NULL AND pay_serial_no IS NOT NULL AND pay_serial_no COLLATE utf8mb4_0900_ai_ci<>CONVERT(middle_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci)) OR (:ruleCode='CHANNEL_MISSING' AND (middle_status=4 AND channel_success_n=0)) OR (:ruleCode='CHANNEL_AMOUNT' AND (middle_status=4 AND channel_success_n>0 AND NOT(middle_amount <=> channel_actual))) OR (:ruleCode='CHANNEL_CODE' AND (status=4 AND channel_success_n=1 AND NOT(channel <=> success_channel))) ORDER BY id LIMIT :sampleLimit;

-- 智能柜缴费单生成 [ol_order_slip_generation]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_order.lease_apply LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.first_payment_slip_no AS business_key,p.first_payment_amount AS expected_amount,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.first_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT SUM(d.total_amount) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.first_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_amount FROM ol_order.lease_apply p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.first_payment_amount>0 AND p.service_status>=153) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN generated_n=0 THEN 1 ELSE 0 END),0) AS GENERATION_MISSING_n,COALESCE(SUM(CASE WHEN generated_n=0 THEN ABS(expected_amount) ELSE 0 END),0) AS GENERATION_MISSING_diff,COALESCE(SUM(CASE WHEN generated_n>0 AND NOT(expected_amount <=> generated_amount) THEN 1 ELSE 0 END),0) AS GENERATION_AMOUNT_n,COALESCE(SUM(CASE WHEN generated_n>0 AND NOT(expected_amount <=> generated_amount) THEN ABS(expected_amount-generated_amount) ELSE 0 END),0) AS GENERATION_AMOUNT_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.first_payment_slip_no AS business_key,p.first_payment_amount AS expected_amount,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.first_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT SUM(d.total_amount) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.first_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_amount FROM ol_order.lease_apply p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.first_payment_amount>0 AND p.service_status>=153) SELECT id,business_key,expected_amount,generated_n,generated_amount FROM q WHERE (:ruleCode='GENERATION_MISSING' AND (generated_n=0)) OR (:ruleCode='GENERATION_AMOUNT' AND (generated_n>0 AND NOT(expected_amount <=> generated_amount))) ORDER BY id LIMIT :sampleLimit;

