WITH q AS (SELECT p.id,p.asset_order_no AS business_key,p.procure_price AS expected_amount,(SELECT COUNT(*) FROM lease_finance.payment_order d WHERE d.asset_order_no=CONVERT(p.asset_order_no USING utf8) COLLATE utf8_general_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT SUM(d.amount) FROM lease_finance.payment_order d WHERE d.asset_order_no=CONVERT(p.asset_order_no USING utf8) COLLATE utf8_general_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_amount FROM lease_finance.asset_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.trans_model IN ('1','2') AND p.asset_source=1) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN generated_n=0 THEN 1 ELSE 0 END),0) AS GENERATION_MISSING_n,COALESCE(SUM(CASE WHEN generated_n=0 THEN ABS(expected_amount) ELSE 0 END),0) AS GENERATION_MISSING_diff,COALESCE(SUM(CASE WHEN generated_n>0 AND NOT(expected_amount <=> generated_amount) THEN 1 ELSE 0 END),0) AS GENERATION_AMOUNT_n,COALESCE(SUM(CASE WHEN generated_n>0 AND NOT(expected_amount <=> generated_amount) THEN ABS(expected_amount-generated_amount) ELSE 0 END),0) AS GENERATION_AMOUNT_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.asset_order_no AS business_key,p.procure_price AS expected_amount,(SELECT COUNT(*) FROM lease_finance.payment_order d WHERE d.asset_order_no=CONVERT(p.asset_order_no USING utf8) COLLATE utf8_general_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT SUM(d.amount) FROM lease_finance.payment_order d WHERE d.asset_order_no=CONVERT(p.asset_order_no USING utf8) COLLATE utf8_general_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_amount FROM lease_finance.asset_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.trans_model IN ('1','2') AND p.asset_source=1) SELECT id,business_key,expected_amount,generated_n,generated_amount FROM q WHERE (:ruleCode='GENERATION_MISSING' AND (generated_n=0)) OR (:ruleCode='GENERATION_AMOUNT' AND (generated_n>0 AND NOT(expected_amount <=> generated_amount))) ORDER BY id LIMIT :sampleLimit;

-- 智能柜账单生成 [ol_saps_bill_generation]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_order.loan_funder_repayment_schedule LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.schedule_code AS business_key,p.application_code,p.period,p.repay_total_amount,(SELECT COUNT(*) FROM ol_saps.customer_bill d WHERE d.application_no=CONVERT(p.application_code USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND d.pid=CONVERT(p.schedule_code USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n FROM ol_order.loan_funder_repayment_schedule p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.schedule_class='1' AND EXISTS(SELECT 1 FROM ol_order.lease_apply a WHERE a.application_code=p.application_code AND a.service_status IN (180,181,182) AND COALESCE(a.is_delete,0)=0 AND COALESCE(a.is_cancel,0)=0)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN generated_n=0 THEN 1 ELSE 0 END),0) AS GENERATION_MISSING_n,COALESCE(SUM(CASE WHEN generated_n=0 THEN ABS(repay_total_amount) ELSE 0 END),0) AS GENERATION_MISSING_diff,COALESCE(SUM(CASE WHEN generated_n>1 THEN 1 ELSE 0 END),0) AS GENERATION_DUPLICATE_n,COALESCE(SUM(CASE WHEN generated_n>1 THEN ABS(0) ELSE 0 END),0) AS GENERATION_DUPLICATE_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.schedule_code AS business_key,p.application_code,p.period,p.repay_total_amount,(SELECT COUNT(*) FROM ol_saps.customer_bill d WHERE d.application_no=CONVERT(p.application_code USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND d.pid=CONVERT(p.schedule_code USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n FROM ol_order.loan_funder_repayment_schedule p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.schedule_class='1' AND EXISTS(SELECT 1 FROM ol_order.lease_apply a WHERE a.application_code=p.application_code AND a.service_status IN (180,181,182) AND COALESCE(a.is_delete,0)=0 AND COALESCE(a.is_cancel,0)=0)) SELECT id,business_key,application_code,period,repay_total_amount,generated_n FROM q WHERE (:ruleCode='GENERATION_MISSING' AND (generated_n=0)) OR (:ruleCode='GENERATION_DUPLICATE' AND (generated_n>1)) ORDER BY id LIMIT :sampleLimit;

-- 叉车账单生成 [lease_saps_bill_generation]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM lease_finance.loan_customer_repayment_schedule LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.schedule_code AS business_key,p.application_code,p.period,p.repay_total_amount,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.application_no=CONVERT(p.application_code USING utf8mb4) COLLATE utf8mb4_general_ci AND d.period=p.period AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.application_no=CONVERT(p.application_code USING utf8mb4) COLLATE utf8mb4_general_ci AND d.pid=CONVERT(p.schedule_code USING utf8mb4) COLLATE utf8mb4_general_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS exact_link_n FROM lease_finance.loan_customer_repayment_schedule p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.schedule_class='1' AND EXISTS(SELECT 1 FROM lease_finance.loan_apply a WHERE a.loan_code=p.loan_code AND a.status=360 AND COALESCE(a.is_delete,0)=0 AND COALESCE(a.is_cancel,0)=0)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN generated_n=0 THEN 1 ELSE 0 END),0) AS GENERATION_MISSING_n,COALESCE(SUM(CASE WHEN generated_n=0 THEN ABS(repay_total_amount) ELSE 0 END),0) AS GENERATION_MISSING_diff,COALESCE(SUM(CASE WHEN generated_n>1 THEN 1 ELSE 0 END),0) AS GENERATION_DUPLICATE_n,COALESCE(SUM(CASE WHEN generated_n>1 THEN ABS(0) ELSE 0 END),0) AS GENERATION_DUPLICATE_diff,COALESCE(SUM(CASE WHEN generated_n>0 AND exact_link_n=0 THEN 1 ELSE 0 END),0) AS PLAN_LINK_n,COALESCE(SUM(CASE WHEN generated_n>0 AND exact_link_n=0 THEN ABS(0) ELSE 0 END),0) AS PLAN_LINK_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.schedule_code AS business_key,p.application_code,p.period,p.repay_total_amount,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.application_no=CONVERT(p.application_code USING utf8mb4) COLLATE utf8mb4_general_ci AND d.period=p.period AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT COUNT(*) FROM lease_saps.customer_bill d WHERE d.application_no=CONVERT(p.application_code USING utf8mb4) COLLATE utf8mb4_general_ci AND d.pid=CONVERT(p.schedule_code USING utf8mb4) COLLATE utf8mb4_general_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS exact_link_n FROM lease_finance.loan_customer_repayment_schedule p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.schedule_class='1' AND EXISTS(SELECT 1 FROM lease_finance.loan_apply a WHERE a.loan_code=p.loan_code AND a.status=360 AND COALESCE(a.is_delete,0)=0 AND COALESCE(a.is_cancel,0)=0)) SELECT id,business_key,application_code,period,repay_total_amount,generated_n,exact_link_n FROM q WHERE (:ruleCode='GENERATION_MISSING' AND (generated_n=0)) OR (:ruleCode='GENERATION_DUPLICATE' AND (generated_n>1)) OR (:ruleCode='PLAN_LINK' AND (generated_n>0 AND exact_link_n=0)) ORDER BY id LIMIT :sampleLimit;

-- 智能柜退款 [ol_saps_refund]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_saps.refund_order LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.refund_no AS business_key,p.refund_status,p.apply_refund_amount,p.refunded_amount,(SELECT COALESCE(SUM(d.refund_amount),0) FROM ol_saps.refund_payment_flow d WHERE d.refund_no=p.refund_no AND d.request_status='SUCCESS' AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS flow_amount,(SELECT COUNT(*) FROM ol_saps.refund_payment_flow d WHERE d.refund_no=p.refund_no AND d.request_status='SUCCESS' AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0 AND NOT EXISTS(SELECT 1 FROM ol_saps.customer_order o WHERE o.biz_no=d.request_no AND o.status=4 AND o.sub_type IN (3003,3004,3005) AND COALESCE(o.is_delete,0)=0 AND COALESCE(o.is_cancel,0)=0)) AS missing_order FROM ol_saps.refund_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN NOT(refunded_amount <=> flow_amount) THEN 1 ELSE 0 END),0) AS REFUND_FLOW_n,COALESCE(SUM(CASE WHEN NOT(refunded_amount <=> flow_amount) THEN ABS(refunded_amount-flow_amount) ELSE 0 END),0) AS REFUND_FLOW_diff,COALESCE(SUM(CASE WHEN missing_order>0 THEN 1 ELSE 0 END),0) AS REFUND_ORDER_n,COALESCE(SUM(CASE WHEN missing_order>0 THEN ABS(flow_amount) ELSE 0 END),0) AS REFUND_ORDER_diff,COALESCE(SUM(CASE WHEN refund_status='REFUND_SUCCESS' AND NOT(apply_refund_amount <=> refunded_amount) THEN 1 ELSE 0 END),0) AS REFUND_STATUS_n,COALESCE(SUM(CASE WHEN refund_status='REFUND_SUCCESS' AND NOT(apply_refund_amount <=> refunded_amount) THEN ABS(apply_refund_amount-refunded_amount) ELSE 0 END),0) AS REFUND_STATUS_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.refund_no AS business_key,p.refund_status,p.apply_refund_amount,p.refunded_amount,(SELECT COALESCE(SUM(d.refund_amount),0) FROM ol_saps.refund_payment_flow d WHERE d.refund_no=p.refund_no AND d.request_status='SUCCESS' AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS flow_amount,(SELECT COUNT(*) FROM ol_saps.refund_payment_flow d WHERE d.refund_no=p.refund_no AND d.request_status='SUCCESS' AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0 AND NOT EXISTS(SELECT 1 FROM ol_saps.customer_order o WHERE o.biz_no=d.request_no AND o.status=4 AND o.sub_type IN (3003,3004,3005) AND COALESCE(o.is_delete,0)=0 AND COALESCE(o.is_cancel,0)=0)) AS missing_order FROM ol_saps.refund_order p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,refund_status,apply_refund_amount,refunded_amount,flow_amount,missing_order FROM q WHERE (:ruleCode='REFUND_FLOW' AND (NOT(refunded_amount <=> flow_amount))) OR (:ruleCode='REFUND_ORDER' AND (missing_order>0)) OR (:ruleCode='REFUND_STATUS' AND (refund_status='REFUND_SUCCESS' AND NOT(apply_refund_amount <=> refunded_amount))) ORDER BY id LIMIT :sampleLimit;

-- 叉车支付交易及结算 [lease_saps_transaction_settlement]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id,(SELECT COALESCE(MAX(id),0) FROM lease_saps.payment_slip_pay_detail) AS legacy_max_id FROM lease_saps.customer_transaction LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH sp AS (SELECT trans_no,order_no,SUM(pay_amount) AS amount FROM lease_saps.payment_slip_pay_detail WHERE id BETWEEN 1 AND :legacyMaxId AND COALESCE(is_delete,0)=0 AND COALESCE(is_cancel,0)=0 GROUP BY trans_no,order_no),q AS (SELECT p.id,p.serial_no AS business_key,p.order_no,p.status,p.settle_amount,o.sub_type,o.id AS parent_id,(SELECT COALESCE(SUM(d.pay_amount),0) FROM lease_saps.customer_bill_pay_detail d WHERE d.trans_no=p.serial_no AND d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS bill_paid,COALESCE(sp.amount,0) AS slip_paid FROM lease_saps.customer_transaction p LEFT JOIN sp ON sp.trans_no=p.serial_no AND sp.order_no=p.order_no LEFT JOIN lease_saps.customer_order o ON o.order_no=p.order_no AND o.tenant_code <=> p.tenant_code AND COALESCE(o.is_delete,0)=0 AND COALESCE(o.is_cancel,0)=0 WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.status=4) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN parent_id IS NULL THEN 1 ELSE 0 END),0) AS ORDER_MISSING_n,COALESCE(SUM(CASE WHEN parent_id IS NULL THEN ABS(settle_amount) ELSE 0 END),0) AS ORDER_MISSING_diff,COALESCE(SUM(CASE WHEN sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> bill_paid+slip_paid) THEN 1 ELSE 0 END),0) AS SETTLEMENT_AMOUNT_n,COALESCE(SUM(CASE WHEN sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> bill_paid+slip_paid) THEN ABS(settle_amount-bill_paid-slip_paid) ELSE 0 END),0) AS SETTLEMENT_AMOUNT_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH sp AS (SELECT trans_no,order_no,SUM(pay_amount) AS amount FROM lease_saps.payment_slip_pay_detail WHERE id BETWEEN 1 AND :legacyMaxId AND COALESCE(is_delete,0)=0 AND COALESCE(is_cancel,0)=0 GROUP BY trans_no,order_no),q AS (SELECT p.id,p.serial_no AS business_key,p.order_no,p.status,p.settle_amount,o.sub_type,o.id AS parent_id,(SELECT COALESCE(SUM(d.pay_amount),0) FROM lease_saps.customer_bill_pay_detail d WHERE d.trans_no=p.serial_no AND d.order_no=p.order_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS bill_paid,COALESCE(sp.amount,0) AS slip_paid FROM lease_saps.customer_transaction p LEFT JOIN sp ON sp.trans_no=p.serial_no AND sp.order_no=p.order_no LEFT JOIN lease_saps.customer_order o ON o.order_no=p.order_no AND o.tenant_code <=> p.tenant_code AND COALESCE(o.is_delete,0)=0 AND COALESCE(o.is_cancel,0)=0 WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.status=4) SELECT id,business_key,order_no,status,sub_type,settle_amount,bill_paid,slip_paid FROM q WHERE (:ruleCode='ORDER_MISSING' AND (parent_id IS NULL)) OR (:ruleCode='SETTLEMENT_AMOUNT' AND (sub_type IN (2000,2001,2002,2100,3006) AND NOT(settle_amount <=> bill_paid+slip_paid))) ORDER BY id LIMIT :sampleLimit;

