-- 智能柜付款审核及代付 [ol_order_remit]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_order.payment_order_batch_audit LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.fk_order_no,p.pay_status,p.pay_serial_no,o.id AS payable_id,o.paid_amount,r.id AS remit_id,r.status AS remit_status,r.transaction_amount FROM ol_order.payment_order_batch_audit p LEFT JOIN ol_order.payment_order o ON o.order_no=p.fk_order_no AND COALESCE(o.is_delete,0)=0 AND COALESCE(o.is_cancel,0)=0 LEFT JOIN xxt_pay.remit_order r ON r.serial_no=CONVERT(p.pay_serial_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(r.is_delete,0)=0 AND COALESCE(r.is_cancel,0)=0 WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN payable_id IS NULL THEN 1 ELSE 0 END),0) AS PAYABLE_MISSING_n,COALESCE(SUM(CASE WHEN payable_id IS NULL THEN ABS(0) ELSE 0 END),0) AS PAYABLE_MISSING_diff,COALESCE(SUM(CASE WHEN pay_status='SUCCESS' AND remit_id IS NULL THEN 1 ELSE 0 END),0) AS REMIT_MISSING_n,COALESCE(SUM(CASE WHEN pay_status='SUCCESS' AND remit_id IS NULL THEN ABS(paid_amount) ELSE 0 END),0) AS REMIT_MISSING_diff,COALESCE(SUM(CASE WHEN remit_id IS NOT NULL AND ((pay_status='SUCCESS')<>(remit_status='SUCCESS')) THEN 1 ELSE 0 END),0) AS REMIT_STATUS_n,COALESCE(SUM(CASE WHEN remit_id IS NOT NULL AND ((pay_status='SUCCESS')<>(remit_status='SUCCESS')) THEN ABS(paid_amount) ELSE 0 END),0) AS REMIT_STATUS_diff,COALESCE(SUM(CASE WHEN pay_status='SUCCESS' AND remit_status='SUCCESS' AND NOT(paid_amount <=> transaction_amount) THEN 1 ELSE 0 END),0) AS REMIT_AMOUNT_n,COALESCE(SUM(CASE WHEN pay_status='SUCCESS' AND remit_status='SUCCESS' AND NOT(paid_amount <=> transaction_amount) THEN ABS(paid_amount-transaction_amount) ELSE 0 END),0) AS REMIT_AMOUNT_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.serial_no AS business_key,p.fk_order_no,p.pay_status,p.pay_serial_no,o.id AS payable_id,o.paid_amount,r.id AS remit_id,r.status AS remit_status,r.transaction_amount FROM ol_order.payment_order_batch_audit p LEFT JOIN ol_order.payment_order o ON o.order_no=p.fk_order_no AND COALESCE(o.is_delete,0)=0 AND COALESCE(o.is_cancel,0)=0 LEFT JOIN xxt_pay.remit_order r ON r.serial_no=CONVERT(p.pay_serial_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(r.is_delete,0)=0 AND COALESCE(r.is_cancel,0)=0 WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,fk_order_no,pay_status,pay_serial_no,paid_amount,remit_status,transaction_amount FROM q WHERE (:ruleCode='PAYABLE_MISSING' AND (payable_id IS NULL)) OR (:ruleCode='REMIT_MISSING' AND (pay_status='SUCCESS' AND remit_id IS NULL)) OR (:ruleCode='REMIT_STATUS' AND (remit_id IS NOT NULL AND ((pay_status='SUCCESS')<>(remit_status='SUCCESS')))) OR (:ruleCode='REMIT_AMOUNT' AND (pay_status='SUCCESS' AND remit_status='SUCCESS' AND NOT(paid_amount <=> transaction_amount))) ORDER BY id LIMIT :sampleLimit;

-- 叉车付款审核及代付 [lease_finance_remit]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM lease_finance.payment_order LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.payment_no AS business_key,p.payment_result,p.pay_amount,p.payment_serial_no,r.id AS remit_id,r.status AS remit_status,r.transaction_amount FROM lease_finance.payment_order p LEFT JOIN lease_payment.remit_order r ON r.biz_serial_no=p.payment_serial_no COLLATE utf8_general_ci AND COALESCE(r.is_delete,0)=0 AND COALESCE(r.is_cancel,0)=0 WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN payment_result=4 AND remit_id IS NULL THEN 1 ELSE 0 END),0) AS REMIT_MISSING_n,COALESCE(SUM(CASE WHEN payment_result=4 AND remit_id IS NULL THEN ABS(pay_amount) ELSE 0 END),0) AS REMIT_MISSING_diff,COALESCE(SUM(CASE WHEN remit_id IS NOT NULL AND ((payment_result=4)<>(remit_status=4)) THEN 1 ELSE 0 END),0) AS REMIT_STATUS_n,COALESCE(SUM(CASE WHEN remit_id IS NOT NULL AND ((payment_result=4)<>(remit_status=4)) THEN ABS(pay_amount) ELSE 0 END),0) AS REMIT_STATUS_diff,COALESCE(SUM(CASE WHEN payment_result=4 AND remit_status=4 AND NOT(pay_amount <=> transaction_amount) THEN 1 ELSE 0 END),0) AS REMIT_AMOUNT_n,COALESCE(SUM(CASE WHEN payment_result=4 AND remit_status=4 AND NOT(pay_amount <=> transaction_amount) THEN ABS(pay_amount-transaction_amount) ELSE 0 END),0) AS REMIT_AMOUNT_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.payment_no AS business_key,p.payment_result,p.pay_amount,p.payment_serial_no,r.id AS remit_id,r.status AS remit_status,r.transaction_amount FROM lease_finance.payment_order p LEFT JOIN lease_payment.remit_order r ON r.biz_serial_no=p.payment_serial_no COLLATE utf8_general_ci AND COALESCE(r.is_delete,0)=0 AND COALESCE(r.is_cancel,0)=0 WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,payment_result,pay_amount,payment_serial_no,remit_status,transaction_amount FROM q WHERE (:ruleCode='REMIT_MISSING' AND (payment_result=4 AND remit_id IS NULL)) OR (:ruleCode='REMIT_STATUS' AND (remit_id IS NOT NULL AND ((payment_result=4)<>(remit_status=4)))) OR (:ruleCode='REMIT_AMOUNT' AND (payment_result=4 AND remit_status=4 AND NOT(pay_amount <=> transaction_amount))) ORDER BY id LIMIT :sampleLimit;

-- 智能柜验收缴费单生成 [ol_order_acceptance_slip]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_order.lease_apply LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.acceptance_payment_slip_no AS business_key,p.acceptance_payment_slip_amount AS expected_amount,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.acceptance_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT SUM(d.total_amount) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.acceptance_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_amount FROM ol_order.lease_apply p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.acceptance_payment_slip_amount>0 AND p.service_status>=175) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN generated_n=0 THEN 1 ELSE 0 END),0) AS GENERATION_MISSING_n,COALESCE(SUM(CASE WHEN generated_n=0 THEN ABS(expected_amount) ELSE 0 END),0) AS GENERATION_MISSING_diff,COALESCE(SUM(CASE WHEN generated_n>0 AND NOT(expected_amount <=> generated_amount) THEN 1 ELSE 0 END),0) AS GENERATION_AMOUNT_n,COALESCE(SUM(CASE WHEN generated_n>0 AND NOT(expected_amount <=> generated_amount) THEN ABS(expected_amount-generated_amount) ELSE 0 END),0) AS GENERATION_AMOUNT_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.acceptance_payment_slip_no AS business_key,p.acceptance_payment_slip_amount AS expected_amount,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.acceptance_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_n,(SELECT SUM(d.total_amount) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.acceptance_payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS generated_amount FROM ol_order.lease_apply p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime) AND p.acceptance_payment_slip_amount>0 AND p.service_status>=175) SELECT id,business_key,expected_amount,generated_n,generated_amount FROM q WHERE (:ruleCode='GENERATION_MISSING' AND (generated_n=0)) OR (:ruleCode='GENERATION_AMOUNT' AND (generated_n>0 AND NOT(expected_amount <=> generated_amount))) ORDER BY id LIMIT :sampleLimit;

-- 智能柜拆单批次生成 [ol_order_batch_generation]
-- 高水位查询
SELECT COALESCE(MIN(id),0) AS min_id,COALESCE(MAX(id),0) AS max_id FROM ol_order.lease_apply_batch LIMIT 1;

-- 汇总：startId/endId 主键分批；日期参数传 NULL 表示全量
WITH q AS (SELECT p.id,p.batch_no AS business_key,p.batch_status,p.payment_slip_amount,p.purchase_price,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS slip_n,(SELECT COUNT(*) FROM ol_order.payment_order d WHERE d.batch_no=p.batch_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS payable_n FROM ol_order.lease_apply_batch p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND p.batch_status>=10 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT COUNT(*) AS checked_count,COALESCE(SUM(CASE WHEN payment_slip_amount>0 AND slip_n=0 THEN 1 ELSE 0 END),0) AS SLIP_GENERATION_n,COALESCE(SUM(CASE WHEN payment_slip_amount>0 AND slip_n=0 THEN ABS(payment_slip_amount) ELSE 0 END),0) AS SLIP_GENERATION_diff,COALESCE(SUM(CASE WHEN batch_status=30 AND purchase_price>0 AND payable_n=0 THEN 1 ELSE 0 END),0) AS PAYABLE_GENERATION_n,COALESCE(SUM(CASE WHEN batch_status=30 AND purchase_price>0 AND payable_n=0 THEN ABS(purchase_price) ELSE 0 END),0) AS PAYABLE_GENERATION_diff FROM q LIMIT 1;

-- 单规则样本：ruleCode 带引号，sampleLimit <= 20
WITH q AS (SELECT p.id,p.batch_no AS business_key,p.batch_status,p.payment_slip_amount,p.purchase_price,(SELECT COUNT(*) FROM ol_saps.payment_slip d WHERE d.serial_no=CONVERT(p.payment_slip_no USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS slip_n,(SELECT COUNT(*) FROM ol_order.payment_order d WHERE d.batch_no=p.batch_no AND COALESCE(d.is_delete,0)=0 AND COALESCE(d.is_cancel,0)=0) AS payable_n FROM ol_order.lease_apply_batch p WHERE p.id BETWEEN :startId AND :endId AND COALESCE(p.is_delete,0)=0 AND COALESCE(p.is_cancel,0)=0 AND p.batch_status>=10 AND (:startDateTime IS NULL OR p.create_time>=:startDateTime) AND (:endExclusiveDateTime IS NULL OR p.create_time<:endExclusiveDateTime)) SELECT id,business_key,batch_status,payment_slip_amount,purchase_price,slip_n,payable_n FROM q WHERE (:ruleCode='SLIP_GENERATION' AND (payment_slip_amount>0 AND slip_n=0)) OR (:ruleCode='PAYABLE_GENERATION' AND (batch_status=30 AND purchase_price>0 AND payable_n=0)) ORDER BY id LIMIT :sampleLimit;

